algorithms.pseudocode:
Algorithm MinimalExchangeConstant(p, n):
    K_max <- 0
    for each (a, b) in support(p) x support(p):
        for each coordinate i with b_i < a_i:
            K_best <- infinity
            for each coordinate j with a_j < b_j:
                a_prime <- exchangeDown(a, i, j)
                b_prime <- exchangeUp(b, i, j)
                if coeff(a_prime) != 0 and coeff(b_prime) != 0:
                    K_best <- min(K_best, coeff(a)*coeff(b) / (coeff(a_prime)*coeff(b_prime)))
            K_max <- max(K_max, K_best)
    return K_max

Time: O(|S|^2 * n^2), Space: O(|S|)
